float plaI( Ray ray, vec3 normal,float shift )
{
    float dis = dot(normal,ray.d);
    if (-dis > 0.001){
        float t = dot(vec3(shift)-ray.o,normal)/dis ;
        return t ;
    } 
    else return -1. ;
}
vec2  sphI(vec3 ro,vec3 rd, vec4 sph) 
{ 
    vec3 oc = ro - sph.rgb; 
    float b = dot( oc, rd ); 
    float c = dot( oc, oc ) - sph.a*sph.a; 
    float h = b*b - c; 
    if( h<0.0 ) return vec2(-1.) ; 
    h = sqrt( h ); 
    return vec2(-b-h,-b+h); 
}
