float HG( float g, float sundotrd) {
	float gg = g * g;	return (1. - gg) / pow( 1. + gg - 2. * g * sundotrd, 1.5);
}

float phase(float f, float b, float u) {
    return mix(HG(f, u), HG(b, u), 0.5);
} 
float rayleigh(float u) {

    return 0.75 * (1. + clamp(u*u, 0.,1.)) ;

} 
mat3 rotAxis(vec3 axis, float a) {
    float s=sin(a);
    float c=cos(a);
    float oc=1.0-c;
    vec3 as=axis*s;
    mat3 p=mat3(axis.x*axis,axis.y*axis,axis.z*axis);
    mat3 q=mat3(c,-as.z,as.y,as.z,c,-as.x,-as.y,as.x,c);
    return p*oc+q;
}

vec3 sky(vec3 rd) {
    float costh0 = dot(rd,SUN) ;
    float blend = smoothstep(-1.,0.6,costh0);
    float mult = smoothstep(-0.5,0.7,costh0) * 0.5 + 0.5;
    vec3 day = mix(vec3(0.3,0.6,1.)*0.7 * rayleigh(costh0) , vec3(0.9,0.95,1.),exp(-abs(rd.y) * 5.));
    vec3 even = mix(vec3(0.3,0.6,1.)*0.7, mix(vec3(0.2,0.3,0.4), vec3(1.,0.2,0.),blend), exp(-abs(rd.y) * 5.));
    vec3 sun = 0.02/ length(rd-SUN) * SUNCOLOR ;

    vec3 night = vec3(0.05, 0.1,0.2) + clamp(0.02 / length(rd+SUN),0.,1.) * vec3(0.7,0.8,1.) * 0.6;
    vec3 dayF = mix(day, even, exp(-abs(SUN.y) * 5.)) + sun;

    float earth = smoothstep(-0.02,0.02,rd.y) * 0.5 + 0.5;

    float mieM = 1.-abs(dot(SUN, vec3(0.,1.,0.))) + 0.3;
    return mix(night, dayF + HG(0.6,costh0) * SUNCOLOR * 0.3 * mieM, smoothstep(-0.2,0.0,SUN.y)) * earth;
    //return vec3(HG(0.9,costh0)) ;
} 
