float fbm(vec3 x, int octaves) {
    float v = 0.0;
    float a = 0.5;
    x += vec3(-iTime * 0.01) ;
    vec3 shift = vec3(100);
    for (int i = 0; i < octaves; ++i) {
        v += a * texture(iChannel0, x).r;
        x = x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}
float fbm2D(vec2 x, int octaves) {
    float v = 0.0;
    float a = 0.5;
    //x+=vec3(iTime) ;
    vec2 shift = vec2(100);
    for (int i = 0; i < octaves; ++i) {
        v += a * texture(iChannel1, x).r;
        x = x * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}
vec4 evalDensity(vec3 p) {
    p.xz += iTime * 100.;
    float h01 = (p.y - cloudH) / thickness ;
    if(h01< 0. || h01 > 1.) return vec4(0.);

    float gradient = smoothstep(0.,0.1,h01) * smoothstep(1.,0.1,h01);
    float coverage = smoothstep(0.,1. ,fbm2D(p.xz / 200000.,2) + (coverageAmount - 1.) * 0.2);
    float cloudType = smoothstep(0.3,0.7,fbm2D(p.xz / 1e10, 2)) ;

    //float noise = (1.-worley(p/2000.)) * 1.5;
    float noise = fbm(p/20000.,8) ;
    float d = smoothstep(0.14,0.17,gradient * noise * coverage) ;
    //d = smoothstep(0.4,0.6,coverage* d) ;
    return vec4(1.,1.,1.,clamp(d * 0.5, 0.,1.));
} 
float opticalDepth(Ray ray, int Tsteps) {
    // we assume we are inside the cloud
    float info = cI(ray).y;
    info = 4000. ;
    float stepL = info / float(Tsteps) * 0.1;
    float t = 1. ;
    float t2 = 1. ;
    for (int i = 0 ; i < Tsteps ; i++) {
        float dither = 0.7 + 0.6 * texture(iChannel2, ray.o.xz + ray.o.y).r;
        ray.o += ray.d * stepL * dither;

        float volD = evalDensity(ray.o).a;

        if(volD>0.){
            t*= exp(-volD * stepL * sigma_t * dither) ;
            t2*= exp(-volD * stepL * sigma_t * dither * 0.2);
        } 
        stepL *= 2. ;
    } 
    return t;
} 
vec4 rayMarch(Ray ray, vec2 uv) {

    vec2 info = cI(ray) ;

    if(info.x < 0.) return vec4(0., 0., 0., 1.);
    vec3 L = vec3(0.);
    float t = 1. ;

    float stepL = info.y / steps ;
    float d = 0. ;
    ray.o += ray.d * info.x ;
    d+=info.x ;

    float next = stepL ;
    float costheta = dot(ray.d, SUN) ;
    for(int i = 0 ; i < int(steps) ; i++) {
        float dither = 0.7 + 0.6 * texture(iChannel2, uv).r;

        ray.o += ray.d * stepL * dither ;

        vec4 vol = evalDensity(ray.o) ;

        if(vol.a > 0.){
            float local = exp(-stepL * vol.a *dither* sigma_t);

            // update light
            float oDsun = 0.;
            float oDmoon = 0.;
            if(SUN.y >= -0.05)
                oDsun = opticalDepth(Ray(ray.o, SUN), 10) * smoothstep(-0.05,0.,SUN.y) ;
            if(SUN.y <= -0.05)
                oDmoon = opticalDepth(Ray(ray.o,-SUN), 5) * (1. - smoothstep(-0.05,0.,SUN.y)) ;
            float ambiant = opticalDepth(Ray(ray.o, vec3(0.,1.,0.)),4) ;

            float phaseVal = phase(0.6,-0.2,costheta) + HG(0.8,costheta) ;
            float phaseMoon = phase(0.6,-0.2,-costheta);
            vec3 light = (oDsun * 3. * SUNCOLOR) * phaseVal + sky(vec3(1.,0.,0.)) * (0.1 + ambiant * 0.5) + phaseMoon * oDmoon * vec3(0.7,0.8,1.) * 0.3;
            vec3 r = vol.a * t * stepL * light * vol.rgb * sigma_s;
            L+=r;

            // update transmittance
            t *= local;


        }
        d+=stepL * dither ;

        if(d > info.x + info.y) break ; 
        //t = smoothstep(0.05,0.5,t) * t;
        if(t < 0.05) {
            //t = 0.;
            break;
        }

    } 
    float atmos = exp(-max(info.x,info.y)* 3e-5);
    vec3 a = sky(vec3(1.,0.,0.)) * 0. * (1. + smoothstep(0.7,1.,costheta) * 1.) ;

    //t-=0.05;
    //return vec4(t) ;
    //t = smoothstep(0.,0.4,t) * t;
    return vec4(mix(sky(ray.d), L + a,atmos), t);
} 
vec4 planar(Ray ray) {
    float plane = plaI(ray,-vec3(0.,1.,0.) * sign(dot(ray.d, vec3(0.,1.,0.))) , 10000.);

    if(plane<0.)return vec4(0.,0.,0.,1.);
    vec3 p = ray.o + ray.d * plane ;
    p.xz += iTime * 1000. ;
    float subs = - 0.15;
    float noise = smoothstep(0.3,0.7,fbm2D(p.xz / vec2(1e6, 2e6) , 8) + subs) ;

    float azimuth = exp(-abs(ray.d.y) * 5.);
    vec3 L = exp(-noise) * SUNCOLOR * 4. * phase(0.6,-0.2,dot(ray.d,SUN)) * smoothstep(-0.1,0.,SUN.y);
    L *= mix(vec3(1.), vec3(1.,0.7,0.5),azimuth);

    float atmos = exp(-plane * 7e-6);
    return vec4(mix(sky(ray.d), L, atmos) , exp(-noise));
    //return vec4(L, exp(-noise)) ;
} 
float sdf(vec3 p) {
    return p.y - pow(fbm2D(p.xz/vec2(1000., 700.) + iTime * 0.01,4),2.) * 1.;
} 
vec3 calcN(vec3 p) { 

    vec2 e = vec2(1.0, -1.0) * 0.4; // epsilon 



    return normalize( 

      e.xyy * sdf(p+e.xyy) + 

      e.yyx * sdf(p+e.yyx) + 

      e.yxy * sdf(p+e.yxy) + 

      e.xxx * sdf(p+e.xxx)) ; 

}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.);

    uv*=3. ;
    float ratio = iResolution.x / iResolution.y ;
    if(abs(uv.x / ratio ) > 0.5 || abs(uv.y) > 0.5) {
        fragColor = vec4(0.);
        return ;
    } 

    //mouse for camera's movement
    vec2 mouse = iMouse.xy/iResolution.xy ;
    if(mouse.x == 0. && mouse.y == 0.) mouse.xy = vec2(0.5);
    vec3 lookAt = vec3(1.-((mouse.x-.5)*360.),(mouse.y-0.5)*180.,0.);

    vec3 ro = vec3(0.,50.,0.);
    vec3 rd = normalize(vec3(uv,-0.5));

    //using matrices for camera rotation
    rd *= rotAxis(vec3(1.,0.,0.),3.141592/2.*lookAt.y/90.);
    rd *= rotAxis(vec3(0.,1.,0.),3.141592*lookAt.x/180.);

    vec3 oldRd = rd;
    float sea = plaI(Ray(ro, rd), vec3(0.,1.,0.),0.) ;
    if(sea > 0.){
        ro += rd * sea;
        rd = reflect(rd, calcN(ro)) ;
    } 
    vec4 plan = planar(Ray(ro, rd)) ;
    vec4 cloud  = rayMarch(Ray(ro,rd), uv);
    col = mix(plan.rgb,sky(rd),plan.a);
    col = mix(cloud.rgb,col, cloud.a);
    if(sea > 0.) {
        float fresnel = pow(1.+ dot(oldRd, calcN(ro)), 5.);
        vec3 seaColor = mix(vec3(0.), vec3(0.4,0.7,1.)*0.3,smoothstep(-0.1,0.,SUN.y));
        col = mix(seaColor, col,fresnel);
        //col = vec3(fresnel) ;
    } 
    //col = cloud.aaa;
    //col = cI(Ray(ro,rd)).y < 0. ? vec3(1.,0.,0.) : vec3(0.) ;

    fragColor = vec4(col, 1.0);
}

