vec3 blur(vec2 uv, sampler2D tex, float kS, int steps, int lv){
    vec3 result = texture(tex, uv).rgb;
    float w = 1. ;

    for(int a = 1 ; a < lv + 1; a++){
        for(float i = 0. ; i < 2. * PI ; i+= 2. * PI / float(steps)){
            vec2 offs = vec2(cos(i),sin(i));

            vec2 p = uv + offs * float(a) * vec2(kS * 0.7, kS) ;

            float l = length(p - uv);
            float cW = 1. - l / (kS * float(lv));
            result += texture(tex, p).rgb * cW;

            w += cW ;
        }
    }

    return result / w;
}

